effect.shader:
vec3 toHsv(vec3 c) {
    float maxC = max(c.r, max(c.g, c.b));
    float minC = min(c.r, min(c.g, c.b));
    float span = maxC - minC;

    float hue = 0.0;
    if (span > 0.00001) {
        if (maxC == c.r) {
            hue = mod((c.g - c.b) / span, 6.0);
        } else if (maxC == c.g) {
            hue = (c.b - c.r) / span + 2.0;
        } else {
            hue = (c.r - c.g) / span + 4.0;
        }
        hue /= 6.0;
    }
    return vec3(hue, maxC > 0.0 ? span / maxC : 0.0, maxC);
}

vec3 toRgb(vec3 hsv) {
    vec3 k = mod(hsv.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0);
    vec3 base = clamp(min(k, 4.0 - k), 0.0, 1.0);
    return hsv.z * mix(vec3(1.0), base, hsv.y);
}

void main() {
    vec4 color = texture(inputImg, acScreenNorm);
    vec4 flipped = color;

    if (space == 1) {
        flipped.r = 1.0 - color.r;
    } else if (space == 2) {
        flipped.g = 1.0 - color.g;
    } else if (space == 3) {
        flipped.b = 1.0 - color.b;
    } else if (space == 4) {
        flipped.a = 1.0 - color.a;
    } else if (space == 5) {
        // Inverte só o brilho e devolve a cor original em cima: o azul continua
        // azul, mas o que era escuro fica claro.
        vec3 hsv = toHsv(color.rgb);
        hsv.z = 1.0 - hsv.z;
        flipped.rgb = toRgb(hsv);
    } else if (space == 6) {
        vec3 hsv = toHsv(color.rgb);
        hsv.x = fract(hsv.x + 0.5);
        flipped.rgb = toRgb(hsv);
    } else {
        flipped.rgb = 1.0 - color.rgb;
    }

    fragColor = flipped;
}
